package br.com.livraria.book.controller; import br.com.livraria.book.model.Categoria; import br.com.livraria.book.service.CategoriaService; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/categoria") public class CategoriaController {private final CategoriaService service; public CategoriaController(CategoriaService service){this.service=service;} @GetMapping public List<Categoria> listar(){return service.listar();} @GetMapping("/{id}") public Categoria buscar(@PathVariable Long id){return service.buscar(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Categoria salvar(@RequestBody Categoria c){return service.salvar(c);} @PutMapping("/{id}") public Categoria atualizar(@PathVariable Long id,@RequestBody Categoria c){return service.atualizar(id,c);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void excluir(@PathVariable Long id){service.excluir(id);} }